const ee = require('@google/earthengine'); 
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kabulPoint = ee.Geometry.Point(69.1755, 34.5228);
  const bufferRadiusMiles = 30; // miles
  const bufferRadiusMeters = bufferRadiusMiles * 1609.34; // convert miles to meters
  const aoi = kabulPoint.buffer(bufferRadiusMeters);

  const start2017 = '2017-02-01';
  const end2017 = '2017-02-28';
  const start2018 = '2018-02-01';
  const end2018 = '2018-02-28';

  const scale = 1000; // MODIS resolution is 1km

  // Function to mask out bad quality pixels (cloudy, etc.)
  // and convert LST to Celsius.
  const processModisLST = function(image) {
    const qc = image.select('QC_Day');
    // Bits 0-1 are LST quality:
    // 00: LST produced, good quality, confidence high
    // 01: LST produced, good quality, confidence low
    // 10: LST produced, questionable quality
    // 11: LST not produced due to cloud, etc.
    // We want only '00' (good quality, high confidence).
    const lstQuality = qc.bitwiseAnd(3); // Extract bits 0 and 1
    const goodQualityMask = lstQuality.eq(0);

    const lst = image.select('LST_Day_1km')
                     .multiply(0.02) // Scale factor for LST_Day_1km
                     .subtract(273.15) // Convert Kelvin to Celsius
                     .updateMask(goodQualityMask); // Apply quality mask
    return lst.rename('LST_Day_Celsius');
  };

  // 2. Data Acquisition & Check
  const modisCollection = ee.ImageCollection('MODIS/061/MOD11A2');

  const collection2017 = modisCollection.filterDate(start2017, end2017)
                                       .filterBounds(aoi);
  const collection2018 = modisCollection.filterDate(start2018, end2018)
                                       .filterBounds(aoi);

  const size2017 = collection2017.size().getInfo();
  const size2018 = collection2018.size().getInfo();

  if (size2017 === 0 || size2018 === 0) {
    console.log(`2017 Images: ${size2017}, 2018 Images: ${size2018}`);
    console.log("C1");
    return;
  }

  // 3. Processing
  // Apply processing to each image in the collection and take the mean
  const processed2017 = collection2017.map(processModisLST);
  const processed2018 = collection2018.map(processModisLST);

  const meanLST2017 = processed2017.mean();
  const meanLST2018 = processed2018.mean();

  // Calculate pixel counts after processing to detect C2
  const count2017 = meanLST2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Day_Celsius').getInfo();

  const count2018 = meanLST2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Day_Celsius').getInfo();

  if (count2017 === 0 || count2018 === 0) {
    console.log(`2017 Images: ${size2017}, Valid Pixels: ${count2017}`);
    console.log(`2018 Images: ${size2018}, Valid Pixels: ${count2018}`);
    console.log("C2");
    return;
  }

  // 4. Calculation
  const temp2017 = meanLST2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Day_Celsius').getInfo();

  const temp2018 = meanLST2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Day_Celsius').getInfo();

  // 5. Validation & Final Answer
  if (temp2017 === null || temp2018 === null || isNaN(temp2017) || isNaN(temp2018)) {
    console.log("C3");
    return;
  }

  console.log(`2017 Images: ${size2017}, Valid Pixels: ${count2017}, Avg Temp: ${temp2017.toFixed(2)}°C`);
  console.log(`2018 Images: ${size2018}, Valid Pixels: ${count2018}, Avg Temp: ${temp2018.toFixed(2)}°C`);

  if (temp2018 > temp2017) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
